import{_ as s,o as t,c as n,al as e}from"./chunks/framework.7vp1BMOE.js";const _=JSON.parse('{"title":"串口映射","description":"","frontmatter":{},"headers":[],"relativePath":"zh/hardware/serial_port_mapping.md","filePath":"zh/hardware/serial_port_mapping.md"}'),p={name:"zh/hardware/serial_port_mapping.md"};function i(o,a,l,d,r,c){return t(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="串口映射" tabindex="-1">串口映射 <a class="header-anchor" href="#串口映射" aria-label="Permalink to &quot;串口映射&quot;">​</a></h1><p>本主题说明如何确定USART/UART串行端口（下称串口）设备名称(例如“ttyS0”)与飞行控制器上对应端口（如<code>TELEM1</code>、<code>TELEM2</code>、<code>GPS1</code>、<code>RC SBUS</code>、<code>调试控制台(Debug console)</code>）之间的映射关系。</p><p>这份说明用于在飞行控制器文档中生成串行端口映射表。 例如： <a href="./../flight_controller/pixhawk4#serial-port-mapping">Pixhawk 4 &gt; Serial Port Mapping</a>。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>每个端口分配的功能不必与名称匹配（大多数情况下），并通过<a href="./../peripherals/serial_configuration">串行端口配置</a>。 通常情况下端口功能是与名称相匹配的，因此标记为<code>GPS1</code>的端口可直接连接GPS设备。</p></div><h2 id="nuttx-在-stmxxyyy-上" tabindex="-1">NuttX 在 STMxxyyy 上 <a class="header-anchor" href="#nuttx-在-stmxxyyy-上" aria-label="Permalink to &quot;NuttX 在 STMxxyyy 上&quot;">​</a></h2><p>本节将展示如何通过检查板载配置文件，获取在 STMxxyyy 架构上构建 NuttX 所需的映射信息。 该说明使用 FMUv5，但同样可扩展至其他FMU版本/NuttX开发板。</p><h3 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h3><p><strong>default.px4board</strong> 文件列出了若干串行端口映射（搜索文本“SERIAL_PORTS”）。</p><p>来自 <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/default.px4board" target="_blank" rel="noreferrer">/boards/px4/fmu-v5/default.px4board</a>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONFIG_BOARD_SERIAL_GPS1=&quot;/dev/ttyS0&quot;</span></span>
<span class="line"><span>CONFIG_BOARD_SERIAL_TEL1=&quot;/dev/ttyS1&quot;</span></span>
<span class="line"><span>CONFIG_BOARD_SERIAL_TEL2=&quot;/dev/ttyS2&quot;</span></span>
<span class="line"><span>CONFIG_BOARD_SERIAL_TEL4=&quot;/dev/ttyS3&quot;</span></span></code></pre></div><p>或者，您可以通过执行 <code>make px4_fmu-v5 boardconfig</code> 启动板配置工具，并进入串口菜单。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    Serial ports  ---&gt;</span></span>
<span class="line"><span>        (/dev/ttyS0) GPS1 tty port</span></span>
<span class="line"><span>        ()  GPS2 tty port</span></span>
<span class="line"><span>        ()  GPS3 tty port</span></span>
<span class="line"><span>        ()  GPS4 tty port</span></span>
<span class="line"><span>        ()  GPS5 tty port</span></span>
<span class="line"><span>        (/dev/ttyS1) TEL1 tty port</span></span>
<span class="line"><span>        (/dev/ttyS2) TEL2 tty port</span></span>
<span class="line"><span>        ()  TEL3 tty port</span></span>
<span class="line"><span>        (/dev/ttyS3) TEL4 tty port</span></span>
<span class="line"><span>        ()  TEL5 tty port</span></span></code></pre></div><h3 id="nsh-defconfig" tabindex="-1">nsh/defconfig <a class="header-anchor" href="#nsh-defconfig" aria-label="Permalink to &quot;nsh/defconfig&quot;">​</a></h3><p><em>nsh/defconfig</em> 允许您确定哪些端口被定义，它们是 UART 还是 USART，以及 USART/UART 与设备之间的映射关系。 您还可以确定用于该功能的端口<a href="./../debug/system_console">串口/调试控制台</a>。</p><p>打开板载的 defconfig 配置文件，例如：<a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/nuttx-config/nsh/defconfig#L215-L221" target="_blank" rel="noreferrer">/boards/px4/fmu-v5/nuttx-config/nsh/defconfig</a></p><p>搜索文本“ART”，直到找到类似以下格式的条目：<code>CONFIG_STM32xx_USARTn=y</code>（其中<code>xx</code>表示处理器类型，<code>n</code>表示端口号）。 例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONFIG_STM32F7_UART4=y</span></span>
<span class="line"><span>CONFIG_STM32F7_UART7=y</span></span>
<span class="line"><span>CONFIG_STM32F7_UART8=y</span></span>
<span class="line"><span>CONFIG_STM32F7_USART1=y</span></span>
<span class="line"><span>CONFIG_STM32F7_USART2=y</span></span>
<span class="line"><span>CONFIG_STM32F7_USART3=y</span></span>
<span class="line"><span>CONFIG_STM32F7_USART6=y</span></span></code></pre></div><p>这些条目会告知您哪些端口已被定义，以及它们属于UART还是USART。</p><p>复制上方段落，按“n”进行数字排序。 同时递增设备编号 <em>ttyS<strong>n</strong></em>（从零开始计数），以获取设备到串行端口的映射关系。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ttyS0 CONFIG_STM32F7_USART1=y</span></span>
<span class="line"><span>ttyS1 CONFIG_STM32F7_USART2=y</span></span>
<span class="line"><span>ttyS2 CONFIG_STM32F7_USART3=y</span></span>
<span class="line"><span>ttyS3 CONFIG_STM32F7_UART4=y</span></span>
<span class="line"><span>ttyS4 CONFIG_STM32F7_USART6=y</span></span>
<span class="line"><span>ttyS5 CONFIG_STM32F7_UART7=y</span></span>
<span class="line"><span>ttyS6 CONFIG_STM32F7_UART8=y</span></span></code></pre></div><p>要获取调试控制台映射，我们需在<a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/nuttx-config/nsh/defconfig#L212" target="_blank" rel="noreferrer">defconfig file</a> 搜索 <code>SERIAL_CONSOLE</code>。 下面我们看到控制台位于UART7：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONFIG_UART7_SERIAL_CONSOLE=y</span></span></code></pre></div><h3 id="board-config-h" tabindex="-1">board_config.h <a class="header-anchor" href="#board-config-h" aria-label="Permalink to &quot;board_config.h&quot;">​</a></h3><p>对于配备IO板的飞行控制器，请通过在<strong>board_config.h</strong>文件中搜索<code>PX4IO_SERIAL_DEVICE</code>来确定PX4IO连接。</p><p>例如 <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v5/src/board_config.h#L59" target="_blank" rel="noreferrer">/boards/px4/fmu-v5/src/board_config.h</a>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define PX4IO_SERIAL_DEVICE            &quot;/dev/ttyS6&quot;</span></span>
<span class="line"><span>#define PX4IO_SERIAL_TX_GPIO           GPIO_UART8_TX</span></span>
<span class="line"><span>#define PX4IO_SERIAL_RX_GPIO           GPIO_UART8_RX</span></span>
<span class="line"><span>#define PX4IO_SERIAL_BASE              STM32_UART8_BASE</span></span></code></pre></div><p>PX4IO 位于 <code>ttyS6</code> 上（我们还可以看到它映射到 UART8，这一点我们从前一节已经知道）。</p><h3 id="整合所有内容" tabindex="-1">整合所有内容 <a class="header-anchor" href="#整合所有内容" aria-label="Permalink to &quot;整合所有内容&quot;">​</a></h3><p>最终映射表如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ttyS0 CONFIG_STM32F7_USART1=y GPS1</span></span>
<span class="line"><span>ttyS1 CONFIG_STM32F7_USART2=y TEL1</span></span>
<span class="line"><span>ttyS2 CONFIG_STM32F7_USART3=y TEL2</span></span>
<span class="line"><span>ttyS3 CONFIG_STM32F7_UART4=y TEL4</span></span>
<span class="line"><span>ttyS4 CONFIG_STM32F7_USART6=y</span></span>
<span class="line"><span>ttyS5 CONFIG_STM32F7_UART7=y DEBUG</span></span>
<span class="line"><span>ttyS6 CONFIG_STM32F7_UART8=y PX4IO</span></span></code></pre></div><p>在 <a href="./../flight_controller/pixhawk4#serial-port-mapping">flight controller docs</a> 最终生成的表格如下：</p><table tabindex="0"><thead><tr><th>UART</th><th>设备</th><th>Port</th></tr></thead><tbody><tr><td>UART1</td><td>/dev/ttyS0</td><td>GPS</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TELEM1 (流控)</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>TELEM2 (流控)</td></tr><tr><td>UART4</td><td>/dev/ttyS3</td><td>TELEM4</td></tr><tr><td>USART6</td><td>/dev/ttyS4</td><td>RC SBUS</td></tr><tr><td>UART7</td><td>/dev/ttyS5</td><td>调试控制台</td></tr><tr><td>UART8</td><td>/dev/ttyS6</td><td>PX4IO</td></tr></tbody></table><h2 id="other-architectures" tabindex="-1">Other Architectures <a class="header-anchor" href="#other-architectures" aria-label="Permalink to &quot;Other Architectures&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Contributions welcome!</p></div><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="./../peripherals/serial_configuration">串口配置</a></li><li><a href="./../peripherals/mavlink_peripherals">MAVLink Telemetry (OSD/GCS)</a></li></ul>`,36)])])}const S=s(p,[["render",i]]);export{_ as __pageData,S as default};
